#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
# The test database is distinct from the development database.
docker compose exec -T db mariadb -uroot -p"${DB_ROOT_PASSWORD:-local_root_only}" -e "CREATE DATABASE IF NOT EXISTS krayin_test; GRANT ALL PRIVILEGES ON krayin_test.* TO 'krayin'@'%';"
docker compose exec -T -e DB_DATABASE=krayin_test app php tools/initialize.php
docker compose exec -T -e DB_DATABASE=krayin_test app php artisan test --compact --cache-directory=/app/.runtime/phpunit tests/Unit/PropertyFavouriteViewTest.php tests/Unit/PropertyModerationTest.php tests/Unit/StayCancellationTest.php tests/Unit/CustomerActionLinkTest.php tests/Unit/StayBookingQuoteTest.php tests/Unit/CustomerIdentityTest.php tests/Unit/CustomerStayBookingViewTest.php tests/Unit/StayContentTest.php tests/Unit/StayStatementTest.php tests/Unit/StayBookingFiltersTest.php tests/Unit/StayPaymentFollowUpTest.php tests/Unit/StayOperationsTest.php tests/Unit/StayCalendarTest.php tests/Unit/StayLedgerTest.php tests/Unit/StayAttendanceTest.php tests/Unit/StayDatesTest.php tests/Unit/PropertyDomainTest.php tests/Unit/LeadFollowUpStateTest.php tests/Unit/SiteVisitStateTest.php tests/Unit/ReportPeriodTest.php tests/Unit/DocumentFilePolicyTest.php tests/Unit/PropertyDealStateTest.php tests/Unit/ApiOriginsTest.php tests/Feature/PropertyApi tests/Feature/AuthenticationTest.php tests/Feature/Leads/LeadPartialUpdateTest.php tests/Feature/Security/AuthenticationHardeningTest.php tests/Feature/Notifications
